        "passage_cn": "滴定实验数据处理原则：\n1. 首次快速试测读数被称为 {b1} (Rough titre)，在最终计算中必须被剔除不计。\n2. 彼此间读数相差在 0.10 cm3 以内的多组平行读数被称为 {b2} 读数 (Concordant)。\n3. 最终记录并参与计算的消耗体积必须是这些有效平行组的 {b3} (Mean)。\n4. 读数紧密闭合在 ±{b4} cm3 之内证明了极高的实验重复可靠性。",
