    "answer_en": "(a) HCl is a strong acid that dissociates completely in water, releasing a much higher concentration of H⁺ ions (lower pH). Ethanoic acid is a weak acid that only partially dissociates, giving fewer H⁺ ions (higher pH).\n(b) Strength refers to degree of dissociation into ions; concentration refers to the amount (moles) of acid dissolved per unit volume of water.",
    "answer_cn": "(a) 盐酸是强酸完全电离，[H⁺] 更高故 pH 更低；乙酸是弱酸仅部分电离，[H⁺] 较低故 pH 较高。\n(b) 强弱指电离程度，浓稀指单位体积溶解的酸的量，二者完全不同。",
