    "prompt_en": "(a) Explain at the particle level why mixing exact amounts of dilute acid and alkali produces a neutral (pH 7) solution. Use the terms H⁺, OH⁻, and water molecules. [2]\n(b) A student mixes acid and alkali in a polystyrene cup. State what happens to the temperature and explain why a polystyrene cup is better than a glass beaker. [2]",
