    "answer_en": "(a) Acidic H⁺ ions combine with alkaline OH⁻ ions to form neutral water molecules (H⁺ + OH⁻ → H₂O), leaving no excess free H⁺ or OH⁻ ions so pH = 7.\n(b) Temperature rises (exothermic reaction). A polystyrene cup is a good thermal insulator, reducing heat loss to the surroundings for a more accurate maximum temperature.",
    "answer_cn": "(a) 酸中的 H⁺ 与碱中的 OH⁻ 结合生成中性水分子（H⁺ + OH⁻ → H₂O），溶液中不再有过量游离 H⁺ 或 OH⁻，故 pH 为 7。\n(b) 温度升高（放热反应）；聚苯乙烯泡沫杯隔热性能好，可减少热量散失，使测得的最高温度更准确。",
